import('https://cdn.jsdelivr.net/npm/@embedpdf/snippet@2/dist/embedpdf.js').then(({default:EmbedPDF})=>{
  document.getElementById('pdfLoading')?.remove();
  EmbedPDF.init({type:'container',target:pdfViewer,src:pdfUrl,theme:{preference:'light'}});
}).catch((error)=>{
  console.error('EmbedPDF could not be loaded',error);
  document.getElementById('pdfLoading')?.remove();
  document.getElementById('pdfFallback').hidden=false;
});
